"""Consolidate independent read-only findings into a reviewable proposal, never game code."""
from pathlib import Path
import json

HERE=Path(__file__).resolve().parent
P='COLDWAR_VIE_'
LABELS={'industrial_capacity_factory':'Rüstungsfabrikausstoß','production_factory_max_efficiency_factor':'maximale Produktionseffizienz','agricolture_productivity_modifier':'Agrarproduktivität','industry_repair_factor':'Gebäudereparatur','bureaucracy_cost_multiplier_modifier':'Bürokratiekosten','social_cost_multiplier_modifier':'Sozialausgaben','education_cost_multiplier_modifier':'Bildungskosten','stability_factor':'Stabilitätsbeitrag','political_power_factor':'politischer Machtgewinn','country_productivity_growth_modifier':'Faktor des Produktivitätswachstums','research_speed_factor':'Forschungsgeschwindigkeit','production_speed_buildings_factor':'Baugeschwindigkeit','imp_sanction_resistance':'Sanktionsresistenz','mdcw_cw_market_exposure':'Übertragung von Weltmarktbooms und Krisen','army_core_defence_factor':'Verteidigung auf vietnamesischem Kerngebiet','army_org_factor':'Armeeorganisation','max_planning_factor':'maximale Planung','supply_consumption_factor':'Versorgungsverbrauch','max_dig_in':'Eingrabungsstufen'}
COSTS={'bureaucracy_cost_multiplier_modifier','social_cost_multiplier_modifier','education_cost_multiplier_modifier','supply_consumption_factor','mdcw_cw_market_exposure'}

def line(k,v):
    if k=='max_dig_in':return f'{v:+g} Eingrabungsstufen'
    if k=='dig_in_speed_factor':return f'{v*100:+g}% Eingrabungsgeschwindigkeit'
    if k=='corporate_tax_income_multiplier_modifier':return f'{v*100:+g}% Körperschaftsteuerertrag, Faktor'
    return f'{v*100:+g}% {LABELS.get(k,k)}'

def main():
    m=json.loads((HERE/'mechanics.json').read_text(encoding='utf-8'))
    h=json.loads((HERE/'history.json').read_text(encoding='utf-8'))
    inv=json.loads((HERE/'inventory.json').read_text(encoding='utf-8'))
    ms={q['id']:q for q in m['proposals']};hs={q['id']:q for q in h['pairs']};sources={q['id']:q for q in h['sources']};by={n['id']:n for n in inv['nodes']}
    issues=[]
    def issue(key,short,area,ids,current,action):
        ids=[P+x for x in ids.split()];assert all(i in by for i in ids)
        issues.append(dict(id=key,short=short,title=short,area=area,ids=ids,current=current,action=action))
    issue('I01','Chinh: 665 Tage in 157 Tagen','Historisches Amtsfenster','chinh_handover chinh_root chinh_documents','Zum Endfokus braucht der kürzeste kompatible Pfad 665 nominale Fokustage. Historisch regiert Chinh im installierten Ablauf nur 157 Tage. Der Zweig verlangt ihn persönlich.','70 Tage Neubewertung und ein inhaltlicher 70-Tage-Entscheid. Anhörungen und Übergabe werden Entscheidungen; institutionelle Ergebnisse können innerhalb derselben Partei fortgeführt werden.')
    issue('I02','Kriegsbonus kommt zu spät','China und Kambodscha','china_hold china_crisis china_depth cambodia_capital','Selbst nach der Vorbereitung verlangt China erst 35 Tage Krise und dann 70 Tage Hold während eines laufenden Krieges. Die große Invasion 1979 dauerte nur 27 verstrichene Tage. Auch Cambodias Hauptstadtbonus benötigt 70 Kriegstage.','Notfallpläne in 70 Tagen vor dem Konflikt vorbereiten. Eine echte Kriegslage aktiviert das verdiente, finanzierte Operationsprogramm sofort; Friedensschluss beendet den Einsatzbonus. Kein Kalender startet einen Krieg.')
    issue('I03','Sechs Fokusse vor der ersten Wahl','Erzwungene Doppelvorbereitung','guerrilla_networks guerrilla_local guerrilla_staff cambodia_mandate china_crisis','Die ersten Kampagnenentscheidungen liegen hinter sechs Pflichtfokussen. Guerrilla benötigt 420 Fokustage und 0,095 Mrd.; Cambodia und China je 385 Tage und 0,100 Mrd. Diese echten UND-Verbindungen sind kein Syntaxfehler, aber ein langer Einstieg.','Je eine glaubwürdige Vorbereitung zusammenfassen. Politische Liaison und Stabsausbildung werden optionale Spezialisierungen statt Pflichtgebühren vor jedem Kriegskurs.')
    issue('I04','Ausbildung läuft im eigenen Pfad ab','Dauer und Wirkung','guerrilla_training guerrilla_staff guerrilla_local','41 von 48 Kampagnenideen laufen nur 180 Tage. Mit 70 Tagen je Folgefokus halten kleine Schulungsboni kaum länger als zwei weitere Fokusse. Regional Staffs entfernt außerdem die vorherige Schulungsstufe.','Ausbildung liefert dauerhafte Erfahrung und begrenzte Doktrinrabatte. Nur konkrete Mobilisierung und Einsätze bleiben befristete, finanzierte Entscheidungen. Folgestufen verbessern einen sinnvollen Kern.')
    issue('I05','Pilotenausbildung hinter Marine','Unpassende Voraussetzung','army_aircrew army_fleet army_coastal','Aircrew Training hängt ausschließlich an Small-Fleet Repairs und dessen Werft. Wer Coastal Defence wählt, sperrt dadurch zugleich die Ausbildung der Luftstreitkräfte.','Die Luftausbildung an gemeinsamen Stab oder Luftverteidigung hängen. Marinealternativen entscheiden über Flottenausbau, nicht über den Zugang zu Piloten.')
    issue('I06','Investitionsfokus hinter Pluralismus','Historisch falsche Kopplung','linh_guarantee linh_pluralism linh_monopoly linh_limited','Investment Access hängt an Political Pluralism. Der Fokus selbst liefert nur Globalismusziel und Marktübertragung; die native FDI-Oberfläche ist dadurch nicht gesperrt. Das Investitionsgesetz 1987 verband Öffnung mit staatlicher Genehmigung.','Kapitalpolitik hinter Enterprise Accounts unabhängig von der Verfassungsfrage aufteilen. Exklusiv ist die konkrete Investitionspriorität, nicht die falsche Behauptung, Prüfung oder Parteiführung schließe FDI aus.')
    issue('I07','Kambodscha zeigt in den falschen Ast','Irreführende Verbindung','cambodia_monitor cambodia_aftermath cambodia_border_settlement cambodia_limited_commitment','Monitor the Agreement führt optisch in Secure the Victory, dessen echte Bedingungen einen militärischen Sieg verlangen. Ein separater begrenzter Ausweg existiert links, die direkte Verbindung bleibt aber irreführend.','Monitor direkt an die begrenzte Grenzregelung führen. Den militärischen Siegpfad für Intervention und tatsächlichen Sieg reservieren; die vorhandene Siegprämie beibehalten.')
    issue('I08','Paris blockiert Hilfe und Handel','Unsichtbare Programmgruppe','diplomacy_moscow diplomacy_balance diplomacy_laos','Sowjetische Hilfe, chinesischer Handel und Paris verwenden dieselbe foreign-Familie. Eine laufende 270-Tage-Vereinbarung kann die beiden anderen blockieren, obwohl sie keine echten Gegensätze sind.','Programme nach tatsächlicher Aufgabe und Partner trennen. Je ein aktiver Donorvertrag und unabhängige Verhandlungen sind möglich; Kosten, Zustimmung, Kapazität und Ablauf bleiben echte Grenzen.')
    issue('I09','Vierzehnmal dieselbe 16er Form','Monotone Schablone','duan_congress chinh_documents linh_statefirms kiet_power','14 von 15 ursprünglichen Bereichen haben exakt 16 Fokusse. Fast jeder Parteizweig wiederholt drei Gabeln mit anschließender Zusammenführung über zehn Ebenen. Saubere Abstände ergeben noch keine eigene politische Dramaturgie.','Kurze persönliche Mandate, langfristige Institutionen und Kriegsphasen unterschiedlich aufbauen. Gemeinsame Infrastruktur nicht in jedem Regierungszweig nochmals als kleinen Zahlenbonus erzählen.')
    issue('I10','Reissicherung ohne Agrarertrag','Schwacher Auftakt','farm_root farm_procure farm_plots','Secure the Rice Supply gibt selbst nur 1% zusätzliche Bürokratiekosten und einen kostenpflichtigen Unlock. Der aktuelle Reisimport gibt 2% Stabilitätsbeitrag und 3% Marktübertragung, aber keine direkte Ernteverbesserung.','Dem Auftakt 6% echte Agrarproduktivität und 1% Sozialausgaben geben. Importhilfe als vorübergehende Versorgungskosten- und Stabilitätsentlastung benennen; keinen erfundenen Getreidevorrat anlegen.')
    issue('I11','Wiederaufbau ohne fertige Kapazität','Startwirtschaft','industry_machine industry_goods industry_root','Alle 16 Bauprojekte werden nur eingereiht. Im nördlichen 1970-Start stehen 0 Zivilkomplexe und 0 Rüstungsfabriken. Leasing und fremde Investitionen helfen, aber ein weiterer Prozentbonus allein schafft keine Baukapazität.','Ein gemeinsamer, finanzierter 70-Tage-Wiederaufbaufokus stellt einmalig 1 Zivilkomplex in Staat 522 fertig: Vorschlag 0,15 Mrd. und 2% Bürokratiekosten für 365 Tage. Die übrigen Projekte bleiben echte Bauvorhaben.')
    issue('I12','70 Tage für kleine Ziffern','Ertrag pro Fokus','duan_heavy duan_balanced guerrilla_lessons dem_tender soc_universal','Viele 70-Tage-Karten tauschen nur 3% bis 6% auf einem einzelnen Faktor gegen laufende Nachteile. The Long War gibt derzeit nur einen einzelnen 15%-Doktrinrabatt.','Schlüsselprogramme bündeln: dauerhafte Kapazität, eine institutionelle Verbesserung und passende Lehre. Dafür kleine Wiederholungen zusammenlegen; nicht alle alten Werte zusätzlich behalten.')
    choices=[]
    def add(mid,title,history_id,focuses,names=None,path='Eine echte Priorität des gleichen Programms, keine lebenslange Unmöglichkeit der anderen Methode.',duration='70 Tage je Fokus',ownership='Ein gewähltes institutionelles Programm; alte kleine Wiederholungsboni werden ersetzt',alts=None,extra=None):
        q=ms[mid];p=q['proposed'];a=alts or p['alternatives'];hist=hs.get(history_id);opts=[]
        for idx,(o,f) in enumerate(zip(a,focuses)):
            good=[];bad=[]
            for k,v in o.get('modifiers',{}).items():
                (bad if ((k in COSTS and v>0) or (k not in COSTS and v<0)) else good).append(line(k,v))
            if not bad:bad.append(o.get('small_downside','Begrenzte Ressourcenbindung'))
            if extra:
                for t in extra.get(idx,[]):good.append(t)
            key=P+f;assert key in by
            opts.append(dict(title=(names or [x['name'] for x in a])[idx],focus=key,benefits=good,drawbacks=bad,current=' · '.join(line(k,v) for k,v in by[key]['modifiers'].items()) or by[key]['label'],mechanics=o))
        src=[dict(label=sources[k]['title'],url=sources[k]['url']) for k in (hist['sources'] if hist else [])]
        choices.append(dict(id=mid,title=title,options=opts,history=hist['rationale_de']+' '+hist['scope_limit_de'] if hist else 'Alternative Regierungspriorität, keine belegte historische Oppositionsplattform. Die genannten Beträge sind Designvorschläge auf Basis nativer MD-Mechaniken.',structure=path,ownership=ownership,duration=duration,sources=src,reference_ids=q['refs'],scope=q['scope']))
    add('M02','Le Duan: Rüstungsbasis oder zivile Erholung','investment_priority',['duan_heavy','duan_balanced'],names=['Complete Priority Industrial Projects','Redirect Resources to Food and Recovery'],path='Beide Alternativen werden erst bei vorhandener militärischer Produktionskapazität angeboten, nativer Zähler num_of_military_factories > 0. Vorher liegt ein gemeinsamer Vorbereitungsweg. Sonst wäre der Rüstungsbonus im 0-MIL-Start wirkungslos. Die konkrete Investition ist exklusiv; Lebensmittel, Konsumgüter und Exporte bleiben ergänzend möglich. Das Branchenprogramm darf normale Nachfolge derselben Partei überdauern; persönliche Autorität bleibt führungsgebunden.')
    choices[-1]['adoption_gate']={'num_of_military_factories':'> 0','applies_to_both':True,'native_reference':'00_generic.txt:5200,5235 uses >3; proposed threshold >0'}
    add('M03','Chinh: ministerielle Zuteilung oder Betriebsautonomie','enterprise_authority',['chinh_subsidy','chinh_autonomy'],names=['Retain Ministerial Allocation','Permit Enterprise Accounting Autonomy'],path='Direkt hinter dem 70-Tage-Auftakt liegt ein gleich langer Sachentscheid: zusammen 140 Tage. Beide Wege kosten einmalig 0,03 Mrd. Die übrigen Untersuchungen wandern in Entscheidungen. Grundversorgung bleibt unter beiden Methoden möglich. Ein übernommenes institutionelles Ergebnis wird bei Linhs regulärer Nachfolge nicht einfach gelöscht.')
    for o in choices[-1]['options']:
        o['mechanics']['cash_bn']=.03
        o['drawbacks'].append('Einmalig 0,03 Mrd. Treasury')
    add('M04','Linh: Arbeitszuteilung oder Mehrertragsvertrag','agricultural_contracts',['linh_contract','linh_coops'],names=['Let Households Retain the Surplus','Maintain Cooperative Work Allocation'],path='Vertragsrechte und Arbeitszuteilung derselben Produktionseinheit entscheiden. Keine allgemeine Sperre zwischen Genossenschaften und Haushalten. Diese spätere Stufe ersetzt die frühere Agrarpriorität; 14% werden nicht zusätzlich zu 10% und allen alten Agrarkarten gestapelt.')
    add('M05','Preisreform: absichern oder schneller umstellen','enterprise_finance',['linh_gradual','linh_shock'],names=['Sequence Reform and Protect Consumption','End Blanket Subsidies with a Transition'],path='Eine gemeinsame Reformfamilie. Die schnellere Umstellung erhält den zusätzlichen Stabilitätsnachteil nur für 365 Tage; sie ist kein automatischer Inflationserfolg und keine zusätzliche Schicht über alten Reformboni.')
    choices[-1]['options'][1]['drawbacks']=['3 Prozentpunkte geringerer Stabilitätsbeitrag für 365 Tage']
    choices[-1]['options'][1]['mechanics']['timed_modifiers']=[dict(days=365,modifiers=dict(stability_factor=-.03))]
    add('M06','Kapitalpolitik unabhängig von der Verfassungsfrage','investment_priority',['linh_limited','linh_guarantee'],names=['Prioritize Strategic State Projects','Prioritize Investment Partnership Infrastructure'],alts=ms['M06']['proposed']['capital_alternatives'],path='Beide Wege beginnen nach Enterprise Accounts und sind mit tatsächlicher Parteiführung vereinbar. Derselbe knappe Investitionsfonds priorisiert strategische Staatsprojekte oder Infrastruktur für Investitionspartnerschaften. Staatskontrolle und ausländische Partnerschaften bleiben unter beiden Wegen möglich. Native FDI bleibt ein eigenständiges, zustimmungspflichtiges System.')
    choices[-1]['sources']=[dict(label=sources['S20']['title'],url=sources['S20']['url']),dict(label=sources['S21']['title'],url=sources['S21']['url'])]
    add('M07','Demokratische Partei: Wettbewerb oder Entwicklungsauftrag',None,['dem_tender','dem_champions'],names=['Competitive Public Procurement','Accountable Development Enterprises'],path='Alternative Regierungspolitik: dieselben öffentlichen Aufträge werden offen ausgeschrieben oder als kontrollierter Entwicklungsauftrag vergeben. Kein generelles Verbot privater oder staatlicher Unternehmen. Regierungsboni ruhen bei Abwahl und kehren nur bei legitimer Rückkehr zurück.')
    add('M08','Sozialistische Partei: allgemeine Dienste oder ländlicher Schwerpunkt',None,['soc_universal','soc_target'],names=['Universal Basic Services','Prioritize Rural Poverty and Literacy'],path='Die nächste zusätzliche Sozialetappe erhält einen Schwerpunkt. Die Partei kann die andere Bevölkerung weiterhin versorgen. Die eigenständige Regierungsrolle dieser historischen Frontpartei ist alternative Geschichte; keine erfundene historische Oppositionsplattform.')
    add('M09','Landwirtschaft: feste Lieferungen oder Mehrertrag','agricultural_contracts',['farm_procure','farm_plots'],names=['Reliable State Procurement','Expand Household Surplus Incentives'],path='Einheitlicher Agrarpolitikkern statt widersprüchlich gestapelter Parteibonusfamilien. Der Auftakt sichert bereits 6% Agrarproduktivität bei 1% Sozialmehrkosten; danach wird die konkrete Beschaffungspriorität gewählt. Keine neue Getreideressource.')
    add('M10','Armee: Heimatverteidigung oder verbundene Kräfte','force_allocation',['army_local','army_combined'],names=['Build Territorial Defence Institutions','Coordinate a Main Force Army'],extra={0:['Einmalig 1 × 25% Landdoktrinkostenrabatt'],1:['Einmalig 1 × 25% Landdoktrinkostenrabatt']},path='Zusätzliche Ausbildung und Organisationsmittel erhalten einen Schwerpunkt. Es existieren weiterhin reguläre und lokale Kräfte. Die spürbaren Pakete ersetzen die kleinen Vorstufen; keine Gratisdivisionen und keine Änderung des aufgeschobenen Start-OOB.')
    for o in choices[-1]['options']:
        o['mechanics']['one_time_effects']=[dict(effect='add_doctrine_cost_reduction',category='land_doctrine',cost_reduction=.25,uses=1)]
    add('M12','Kriegsführung: militärischer Druck oder Verhandlungsmandat','north_south_priority',['unity_pressure','unity_paris'],names=['Concentrate Battlefield Pressure','Strengthen the Negotiating Mandate'],path='Die Ressourcenpriorität ist exklusiv, der Pariser Verhandlungskanal nicht. Beide Wege dürfen kämpfen und verhandeln. Empfänger stimmen Abkommen selbst zu; weder Frieden noch Gebiete werden durch den Fokus erzwungen.')
    a=[dict(name='Hold the Homeland',modifiers={'max_dig_in':5,'dig_in_speed_factor':.25,'army_core_defence_factor':.08,'max_planning_factor':-.05}),dict(name='Prepare a Limited Counterstroke',modifiers={'max_planning_factor':.05,'supply_consumption_factor':.04})]
    add('M14','China: vorbereitete Verteidigung oder begrenzter Gegenstoß','china_frontier_posture',['china_depth','china_objectives'],alts=a,duration='70 Tage Vorbereitung; Einsatzidee maximal 365 Tage und nur bei wirklichem Krieg',ownership='Ein Operationsplan pro Familie; Ende bei Frieden, keine automatische Verlängerung',extra={0:['10% Armeeverteidigung in Wald und Dschungel'],1:['10% Angriff und 3% Verteidigung gegen China']},path='Beide Pläne sind vor dem Krieg erlernbar. Erst ein wirklicher Krieg aktiviert einen verdienten, anfänglich finanzierten Einsatz sofort. Die bereits gewünschten Verteidigungszahlen bleiben unverändert. Der Gegenstoß erhält Planung statt eines zusätzlichen Fabrikmalus; normale spätere Erneuerungen kosten weiterhin Geld.')
    opts=choices[-1]['options']
    opts[0]['mechanics'].update(terrain_training=dict(mechanism='hidden technology active only while operating idea exists',terrains=['forest','jungle'],army_defence=.10),cash_bn=.04,days=365)
    opts[1]['mechanics'].update(target='CHI',targeted_modifiers=dict(attack_bonus_against=.10,defense_bonus_against=.03),cash_bn=.045,days=365)
    for o,cost in zip(opts,['0,04','0,045']):
        o['drawbacks'].append('Einmalig '+cost+' Mrd. für die erste finanzierte Einsatzperiode')
    add('M15','Außenpolitik: technische Bindung oder mehrere Lieferbeziehungen','patron_commitment',['diplomacy_moscow','diplomacy_balance'],names=['Prioritize Soviet Technical Cooperation','Diversify Machinery and Farm Imports'],path='Nur die zusätzliche Bindungspriorität ist exklusiv. Ein sowjetischer, ein chinesischer Vertrag und unabhängige Verhandlungen können parallel bestehen. Reale ausländische Missionen verlangen weiterhin Zustimmung, Kapazität, Zahlung und Ablauf; der Fokus erzeugt keine ausländischen Lieferungen.')
    ms['M16']={'proposed':{'alternatives':[
        dict(name='Place Selected Enterprises under Public Ownership',modifiers=dict(industrial_capacity_factory=.10,production_factory_max_efficiency_factor=.05,bureaucracy_cost_multiplier_modifier=.02)),
        dict(name='License Southern Enterprise',modifiers=dict(country_productivity_growth_modifier=.12,corporate_tax_income_multiplier_modifier=.08,bureaucracy_cost_multiplier_modifier=.02))
    ]},'refs':['SOV_third_way','SOV_UVZ_expanding'],'scope':'National modifiers, not local southern bonuses. The same selected firms cannot have contradictory ownership rules. No repression, ethnic targeting or free property transfers are scripted.'}
    add('M16','Neue Gabel: Eigentumsordnung südlicher Betriebe','southern_transformation',['unity_united','unity_rehabilitate'],duration='70 Tage je neuer Alternative; einmalig 0,05 Mrd. Verwaltungsbudget',ownership='Ein institutionelles Eigentumsstatut; aktive Landesboni nur bei tatsächlicher Südkontrolle',path='Neue exklusive Gabel nach Southern Recovery, nur bei wirklichem Besitz und Kontrolle der Staaten 519, 520 und 521. Dieselben ausgewählten Firmen erhalten öffentliche Trägerschaft oder eine verbindliche private Lizenz. Kein pauschaler Kaufpreis für die Wirtschaft; Repression und individuelle Amnestie bleiben getrennte Themen. Die Familie ersetzt bisherige Integrations-Wachstumsstufen einschließlich des kleinen bisherigen Endbonus. Die Koexistenzroute darf ohne diese Gabel zu Citizens First weitergehen.')
    x=choices[-1]
    x['new_exclusive_pair']=True
    x['adoption_gate']={'tag':'VIE','campaign':'COLDWAR_VIE_is_1970','earned':'COLDWAR_VIE_unity_rehabilitate_reward_applied','owned_and_controlled_states':[519,520,521],'treasury_bn_at_least':.05}
    x['layout']={'new_nodes':{'COLDWAR_VIE_unity_public_enterprises':[32,19],'COLDWAR_VIE_unity_licensed_enterprises':[36,19]},'move':{'COLDWAR_VIE_unity_citizens':[38,20],'COLDWAR_VIE_unity_strict':[37,21],'COLDWAR_VIE_unity_amnesty':[39,21],'COLDWAR_VIE_unity_registry':[37,22],'COLDWAR_VIE_unity_resettle':[39,22],'COLDWAR_VIE_unity_peace':[38,23]},'citizens_prerequisite_or':['COLDWAR_VIE_unity_public_enterprises','COLDWAR_VIE_unity_licensed_enterprises','COLDWAR_VIE_unity_contact'],'review':'Independent native-card geometry review found no card collisions; shifted shared continuation right to prevent coexistence connector from crossing the new licensed-enterprise card. Connector routing remains an approximation until engine review.'}
    for o,suffix in zip(x['options'],['public','licensed']):
        o['new_focus_id']='COLDWAR_VIE_unity_'+('public_enterprises' if suffix=='public' else 'licensed_enterprises')
        o['mechanics']['cash_bn']=.05
        o['drawbacks'].append('Einmalig 0,05 Mrd. Treasury für Verwaltung und Umsetzung')
        o['current']='Neuer Fokus; ersetzt einen Teil des bisherigen kleinen Integrationsprogramms'
    x['structure']+=' Positionen der neuen Wahl: (32, 19) und (36, 19); Citizens First folgt bei (38, 20), damit der Koexistenzanschluss keine neue Karte kreuzt.'
    for x in choices:
        assert len(x['options'])==2 and all(o['benefits'] and o['drawbacks'] for o in x['options'])
        for o in x['options']:o['mechanics']['name']=o['title']
    ms['M01']['proposed']['replaces']='COLDWAR_VIE_industry_goods: relocate and rename the existing Hanoi Workshops project to the common early reconstruction path; remove its old queued grant and old card rather than add a seventeenth building reward'
    ms['M01']['scope']='Replace one of the existing16 queued projects with one completed physical CIV:15 queued projects remain. Ordinary staffing/consumer-goods rules still apply; test actual available construction in-engine. No replay of an already delivered project in existing saves.'
    data=dict(status='Audit and balancing proposals only; NOT installed',date='2026-10-19',issues=issues,choices=choices,
        reconstruction=ms['M01'],training=ms['M13'],preserve=['70-day standard with existing nine exceptions','Current China defensive values','Cambodian actual-victory25XP and two20%doctrine reductions','Actual recipients, expiry, funding and no replay','Starting history, deferred OOB and later starts'],
        limits=['Suggested modifier values use real native APIs; no proposed balance has been engine-tested.','Changing previously earned programme totals requires a save migration; never replay completed factories or XP.','Twelve pairs replace/consolidate existing cards; M16 is a genuinely new exclusive pair replacing part of the former integration rewards.','Some exclusivity is a budget or campaign priority; compatible historical policies stay accessible.'])
    (HERE/'proposals.json').write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    print(json.dumps(dict(issues=len(issues),pairs=len(choices),status=data['status'])))

if __name__=='__main__':main()
